insert into public.categories (slug, no, title, accent, blurb, care, feature_product_id, sort) values
  ('sarees', '01', 'Draped', 'Sarees', 'Six yards and more, with borders and pallus worth unfolding slowly.', 'Dry clean the first few times. Store folded in a cotton cloth and refold now and then.', 'temple-border-saree', 0),
  ('dress-material', '02', 'Dress', 'Material', 'Unstitched sets of top, bottom and dupatta, ready for your own tailor.', 'Wash before stitching to settle the colours. Gentle hand wash in cold water.', 'block-print-set', 1),
  ('coord-sets', '03', 'Co-ord', 'Sets', 'A top and bottom cut from the same cloth, made to be worn together.', 'Gentle hand wash in cold water, inside out. Dry in shade.', 'printed-coord', 2),
  ('gowns', '04', 'Flowing', 'Gowns', 'Floor-length flares for weddings, poojas and every evening in between.', 'Dry clean only. Hang on a padded hanger, away from direct sun.', 'anarkali-gown', 3),
  ('indowestern', '05', 'Indo-western', 'Jewellery', 'Light pieces that sit as well with a dress as with a kurta.', 'Plated alloy, nickel-free. Avoid perfume and water to keep the finish bright.', 'pearl-hoops', 4),
  ('temple', '06', 'Temple', 'Jewellery', 'Gold-tone pieces shaped after the old temple motifs.', 'Plated alloy, nickel-free. Keep dry and store in the cloth pouch it arrives in.', 'temple-jhumka', 5),
  ('oxidised', '07', 'Oxidised', 'Jewellery', 'Darkened silver-look metal, chased and beaded by hand.', 'Oxidised alloy, nickel-free. Keep dry and store in the cloth pouch it arrives in.', 'crescent-chandbali', 6),
  ('potlis', '08', 'Potli', 'Bags', 'Drawstring pouches, embroidered and beaded, to carry with festive clothes.', 'Spot clean only. Store stuffed with tissue so it keeps its shape.', 'embroidered-potli', 7),
  ('torans', '09', 'Doorway', 'Torans', 'Stitched bands and hand-cut flaps that dress a doorway for every arrival.', 'Cotton and thread with glass mirrors and metal bells. Dust gently; spot clean only.', 'haveli-toran', 8),
  ('bandhanwar', '10', 'Festive', 'Bandhanwar', 'Soft swags of pom-poms and tassels to hang across a door or a wall.', 'Wool, felt and cotton. Shake out gently and store flat between seasons.', 'pompom-swag', 9)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort) values
  ('temple-border-saree', 'sarees', 'Temple Border Saree', 'Contrast border, rich pallu', 'A saree with a broad contrast border running down both sides and a pallu banded in zari-look stripes. Ask us on WhatsApp for the fabric, length and blouse piece of each colour.', array['rust','ink','earth']::text[], '{"type":"saree"}'::jsonb, '#EBD3C3', 0),
  ('block-print-set', 'dress-material', 'Block Print Dress Material', 'Top, bottom and dupatta, unstitched', 'A printed length for the top, a plain length for the bottom and a dupatta with tasselled ends, sold together and unstitched, so it can be tailored exactly to you.', array['rust','ink','natural']::text[], '{"type":"fabric"}'::jsonb, '#EFE2C9', 1),
  ('printed-coord', 'coord-sets', 'Printed Co-ord Set', 'Easy top with straight pants', 'A relaxed top and straight pants cut from the same printed cloth, with contrast bands at the hems. Wear them together, or apart with what you already have.', array['earth','rust','ink']::text[], '{"type":"coord"}'::jsonb, '#E4D9C6', 2),
  ('anarkali-gown', 'gowns', 'Flared Anarkali Gown', 'Floor-length, full flare', 'A fitted bodice opening into a deep, many-panelled flare, finished with a heavy border at the hem. Ask us on WhatsApp for sizes and fabric.', array['ink','rust','earth']::text[], '{"type":"gown"}'::jsonb, '#E6D5B4', 3),
  ('pearl-hoops', 'indowestern', 'Pearl Fringe Hoops', 'Hoops dressed in seed pearls', 'Light hoops with a fringe of seed pearls that moves when you do. Easy with a dress, a kurta or a saree.', array['gold-pearl','silver-pearl','gold','silver']::text[], '{"type":"hoops","fringe":true}'::jsonb, '#EBD3C3', 4),
  ('temple-jhumka', 'temple', 'Temple Jhumka', 'Domed bells, beaded fringe', 'Domed jhumkas in a warm gold tone, with a fringe of beads below, after the jewellery carved on temple walls.', array['gold','gold-pearl']::text[], '{"type":"jhumka"}'::jsonb, '#E6D5B4', 5),
  ('crescent-chandbali', 'oxidised', 'Crescent Chandbali', 'Moon-shaped, pearl-edged drops', 'Crescent-moon chandbalis in darkened silver-look metal, edged with small pearls. Light for their size, so you can wear them all evening.', array['oxidised-pearl','oxidised']::text[], '{"type":"chandbali"}'::jsonb, '#E4D9C6', 6),
  ('embroidered-potli', 'potlis', 'Embroidered Potli Bag', 'Drawstring pouch, beaded hem', 'A gathered drawstring potli with an embroidered flower on the front, a beaded edge and tasselled strings. Big enough for a phone, keys and a little more.', array['rust','ink','natural']::text[], '{"type":"potli"}'::jsonb, '#DCC8A5', 7),
  ('haveli-toran', 'torans', 'Haveli Doorway Toran', 'Seven flaps, mirror-stitched band', 'A cotton band edged in running stitch, set with tiny mirrors, and hung with seven pointed flaps. Each flap ends in a small brass-tone bell, so the doorway answers softly when someone walks through.', array['rust','ink','earth','natural']::text[], '{"type":"toran","flaps":7,"shape":"tri","bells":true}'::jsonb, '#EFE2C9', 8),
  ('pompom-swag', 'bandhanwar', 'Pom-pom Swag Garland', 'Woolly pom-poms, three swags', 'Three soft swags of hand-wound wool pom-poms, with tassels at every join. Drape it over a doorway, a mantel or a window.', array['rust','ink','earth','natural']::text[], '{"type":"garland","style":"pompom","swags":3}'::jsonb, '#EFE2C9', 9)
